def max_sum_increasing_subseq(arr, i, k, n):
    if i < 0 or k < 0 or i >= n or k >= n:
        return 0

    # If ith element is greater than kth element, ignore kth element
    if arr[i] > arr[k]:
        return max_sum_increasing_subseq(arr, i-1, k, n)

    # If ith element is not greater than kth element, ignore ith element
    if arr[i] <= arr[k]:
        return max_sum_increasing_subseq(arr, i-1, k, n) + arr[k]

    # If ith element is equal to kth element, ignore both elements
    if arr[i] == arr[k]:
        return max_sum_increasing_subseq(arr, i-1, k, n)

    # If ith element is greater than kth element, include kth element
    return arr[i] + max_sum_increasing_subseq(arr, i-1, k, n) + arr[k]

